with exploded as (select id, plan, effective_from, explode_outer(discounts) as tier_value from price_tiers) select case when tier_value >= 65 then 'LARGE' else 'SMALL' end as tier_value_tier, count(case when plan = 'basic' then 1 end) as basic_count, count(*) filter (where plan = 'pro') as pro_rows, percentile_approx(tier_value, 0.5) as tier_value_p50, round(sum(tier_value) / nullif(count(case when plan = 'pro' then 1 end), 0), 2) as tier_value_per_pro, percentile_approx(tier_value, array(0.25, 0.5, 0.75)) as tier_value_quartiles from exploded group by 1 order by tier_value_per_pro desc
